<script setup lang="ts">
import { ref } from 'vue'
import { api } from '../api'
import { user,refreshUser,perform,busy } from '../state'
import PageHeader from '../components/PageHeader.vue'
import OperationForm from '../components/OperationForm.vue'
const answers=ref<number[]>(Array(10).fill(0)),tab=ref(user.value?.mustChangePassword?'password':'profile')
const questions=['你的主要模拟投资目标是什么？','你对基金产品的了解程度如何？','你希望资金保持多长时间？','你能接受怎样的短期波动？','面对短期下跌时你通常如何决策？','你希望学习哪种资产组合？','你对收益与风险关系的理解如何？','你愿意关注交易记录与信息披露吗？','你希望承担多高的模拟风险？','你如何看待高风险产品的潜在亏损？']
const choices=['偏保守 / 不了解','较保守 / 初步了解','均衡 / 有一定了解','较积极 / 比较了解','积极 / 充分理解']
async function assess(){await perform(async()=>{if(answers.value.some(a=>a<1||a>5))throw new Error('请完成全部十道测评题');return api.post('/risk-assessments',{answers:answers.value})},refreshUser)}
</script>
<template><PageHeader title="账户设置" subtitle="模拟开户、风险测评与账户安全。"/><p v-if="user?.mustChangePassword" class="notice warning">管理员已重置密码。请先设置自己的新密码，完成后才能继续其他业务。</p><div v-if="!user?.mustChangePassword" class="tabs"><button v-for="t in [['profile','客户档案'],['risk','风险测评'],['password','修改密码']]" :key="t[0]" :class="{active:tab===t[0]}" @click="tab=t[0]">{{ t[1] }}</button></div><section v-if="tab==='profile'" class="panel"><h2>我的客户档案</h2><dl class="definition-list"><div><dt>用户名</dt><dd>{{ user?.username }}</dd></div><div><dt>模拟持卡人 / 昵称</dt><dd>{{ user?.displayName }}</dd></div><div><dt>开户状态</dt><dd>{{ user?.opened?'已开通':'尚未开通' }}</dd></div><div><dt>风险等级</dt><dd>{{ user?.riskLevel?'R'+user.riskLevel:'尚未测评' }}</dd></div><div><dt>测评有效期</dt><dd>{{ user?.riskExpiresAt || '尚未测评' }}</dd></div><div><dt>默认交易账户</dt><dd>{{ user?.defaultTradingAccountId || '尚未设置' }}</dd></div></dl><p class="notice" style="margin-top:22px">模拟开户无需真实身份信息。完成开户与有效测评后，新购入还需匹配产品风险等级；测评过期不阻止存量赎回。</p><div class="toolbar"><button v-if="!user?.opened" class="button primary" :disabled="busy>0" @click="perform(()=>api.post('/account/open'),refreshUser)">开通模拟客户账户</button><button class="button" @click="tab='risk'">进行风险测评</button><RouterLink to="/accounts" class="button">管理模拟银行卡</RouterLink></div></section><section v-else-if="tab==='risk'" class="panel"><h2>教学风险问卷</h2><p class="notice">本问卷采用1至5级教学模型，有效期365天。根据你愿意承担的模拟风险作答，不构成真实投资适当性评估。</p><form @submit.prevent="assess"><div v-for="(q,index) in questions" :key="q" class="risk-question"><strong>{{ index+1 }}. {{ q }}</strong><div class="risk-options"><label v-for="(choice,i) in choices" :key="choice"><input v-model="answers[index]" type="radio" :name="'question-'+index" :value="i+1" required/>{{ choice }}</label></div></div><button class="button primary" :disabled="busy>0">{{ busy?'提交中…':'提交测评' }}</button></form></section><OperationForm v-else title="修改登录密码" :fields="[{key:'oldPassword',label:'当前密码',type:'password'}, {key:'newPassword',label:'新密码',type:'password',hint:'至少10位，建议包含大小写字母、数字与符号'}]" :initial="{oldPassword:'',newPassword:''}" :submit="value=>api.post('/account/password',value)" button="更新密码" @saved="refreshUser"/></template>
